referenceSolutions.javascript:
export function solve(tree, tag) {
  const out = [];
  function visit(node) {
    if (tag === "*" || node.tag.toLowerCase() === tag.toLowerCase()) out.push(node.id);
    for (const child of node.children) visit(child);
  }
  visit(tree);
  return out;
}

