type Value = any;
export function solve(tree: Value, tag: Value): Value {
  const out: Value[] = [];
  function visit(node: Value): Value {
    if (tag === "*" || node.tag.toLowerCase() === tag.toLowerCase()) out.push(node.id);
    for (const child of node.children) visit(child);
  }
  visit(tree);
  return out;
}
